package com.example.aspect;

import java.util.Arrays;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.AfterReturning;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.aspectj.lang.annotation.Pointcut;
import org.springframework.stereotype.Component;

// ══ 按包名匹配：controller 层所有公共方法统一记录出入参 ══
@Aspect
@Component
public class ApiLogAspect {

    /**
     * 切点逐段：public = 仅公共方法；* = 任意返回类型；
     * controller..* = controller 包及子包任意类；.*(..) = 任意方法任意参数
     */
    @Pointcut("execution(public * com.example.controller..*.*(..))")
    public void apiLayer() {
    }

    // 前置通知：方法执行前记录签名与入参
    @Before("apiLayer()")
    public void logIn(JoinPoint jp) {
        System.out.println("-> " + jp.getSignature().toShortString()
            + " 入参: " + Arrays.toString(jp.getArgs()));
    }

    // 后置通知：returning = "result" 把返回值绑定进参数
    @AfterReturning(pointcut = "apiLayer()", returning = "result")
    public void logOut(JoinPoint jp, Object result) {
        System.out.println("<- " + jp.getSignature().toShortString()
            + " 出参: " + result);
    }
}

package com.example.aspect;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Method;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.springframework.stereotype.Component;

@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
@interface Audited {
    String action();
}

@Aspect
@Component
public class AuditAspect {

    @Before("@annotation(com.example.aspect.Audited)")
    public void audit(JoinPoint jp) throws NoSuchMethodException {
        Method method = jp.getTarget().getClass()
            .getMethod(jp.getSignature().getName());
        Audited marker = method.getAnnotation(Audited.class);
        System.out.println("[审计] " + marker.action() + " -> "
            + jp.getSignature().getName());
    }
}

// 业务代码：打上注解即被审计，无需改动切面
// @Audited(action = "导出报表")
// public void exportReport() { }
